-- WIP foundation for an offline payment covering multiple installments.
-- Existing payments are not backfilled into batches.
BEGIN;
CREATE UNIQUE INDEX IF NOT EXISTS "AK_StudentAdmissionFeeQuote_Tenant"
    ON skolenza."StudentAdmissionFeeQuote" ("Id", "InstitutionId");
CREATE UNIQUE INDEX IF NOT EXISTS "AK_StudentFeeInstallment_TenantQuote"
    ON skolenza."StudentFeeInstallment" ("Id", "InstitutionId", "StudentAdmissionFeeQuoteId");
CREATE TABLE IF NOT EXISTS skolenza."StudentFeePaymentBatch" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionFeeQuoteId" bigint NOT NULL,
    "IdempotencyKey" varchar(100) NOT NULL,
    "ArrearsPolicy" smallint NOT NULL,
    "SelectedInstallmentId" bigint NULL,
    "Amount" numeric(18,3) NOT NULL,
    "CurrencyCode" varchar(3) NOT NULL,
    "RecordedReference" varchar(150) NULL,
    "RecordedById" bigint NOT NULL,
    "PaidDateTime" timestamp without time zone NOT NULL,
    "AddedDateTime" timestamp with time zone NOT NULL,
    CONSTRAINT "CK_StudentFeePaymentBatch_Amount" CHECK ("Amount" > 0),
    CONSTRAINT "CK_StudentFeePaymentBatch_Policy" CHECK (
        ("ArrearsPolicy" = 1 AND "SelectedInstallmentId" IS NULL) OR
        ("ArrearsPolicy" = 2 AND "SelectedInstallmentId" IS NOT NULL)),
    CONSTRAINT "AK_StudentFeePaymentBatch_TenantQuote" UNIQUE ("Id", "InstitutionId", "StudentAdmissionFeeQuoteId"),
    CONSTRAINT "UX_StudentFeePaymentBatch_Idempotency" UNIQUE ("InstitutionId", "IdempotencyKey"),
    CONSTRAINT "FK_StudentFeePaymentBatch_Quote" FOREIGN KEY ("StudentAdmissionFeeQuoteId", "InstitutionId")
        REFERENCES skolenza."StudentAdmissionFeeQuote" ("Id", "InstitutionId") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeePaymentBatch_SelectedInstallment" FOREIGN KEY
        ("SelectedInstallmentId", "InstitutionId", "StudentAdmissionFeeQuoteId")
        REFERENCES skolenza."StudentFeeInstallment" ("Id", "InstitutionId", "StudentAdmissionFeeQuoteId") ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS skolenza."StudentFeePaymentBatchItem" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentAdmissionFeeQuoteId" bigint NOT NULL,
    "StudentFeePaymentBatchId" bigint NOT NULL,
    "StudentFeeInstallmentId" bigint NOT NULL,
    "StudentFeePaymentTransactionId" bigint NOT NULL,
    CONSTRAINT "UX_StudentFeePaymentBatchItem_Payment" UNIQUE ("StudentFeePaymentTransactionId"),
    CONSTRAINT "UX_StudentFeePaymentBatchItem_Installment" UNIQUE ("StudentFeePaymentBatchId", "StudentFeeInstallmentId"),
    CONSTRAINT "FK_StudentFeePaymentBatchItem_Batch" FOREIGN KEY
        ("StudentFeePaymentBatchId", "InstitutionId", "StudentAdmissionFeeQuoteId")
        REFERENCES skolenza."StudentFeePaymentBatch" ("Id", "InstitutionId", "StudentAdmissionFeeQuoteId") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeePaymentBatchItem_Installment" FOREIGN KEY
        ("StudentFeeInstallmentId", "InstitutionId", "StudentAdmissionFeeQuoteId")
        REFERENCES skolenza."StudentFeeInstallment" ("Id", "InstitutionId", "StudentAdmissionFeeQuoteId") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentFeePaymentBatchItem_Payment" FOREIGN KEY
        ("StudentFeePaymentTransactionId", "InstitutionId", "StudentFeeInstallmentId")
        REFERENCES skolenza."StudentFeePaymentTransaction" ("Id", "InstitutionId", "StudentFeeInstallmentId") ON DELETE RESTRICT
);
COMMIT;
